import { createSignal, For } from 'solid-js';

// ❌ Using <For> on primitive arrays (strings/numbers):
// When number at index 0 changes from 5 to 6, 5 is destroyed and 6 is created as a brand new DOM node!
export default function PrimitiveList() {
  const [numbers, setNumbers] = createSignal([10, 20, 30]);

  return (
    <For each={numbers()}>
      {(num, index) => (
        // ❌ Focus is lost on every keystroke because the input node is re-created:
        <input value={num} onInput={(e) => {
          const next = [...numbers()];
          next[index()] = Number(e.target.value);
          setNumbers(next);
        }} />
      )}
    </For>
  );
}

import { createSignal, Index } from 'solid-js';

// ✅ NEW: <Index> preserves DOM nodes by index slot.
// Updating a value updates the signal without touching DOM element structure.
export default function PrimitiveList() {
  const [numbers, setNumbers] = createSignal([10, 20, 30]);

  return (
    <Index each={numbers()}>
      {(numSignal, index) => (
        // ✅ Input retains focus perfectly! DOM node is reused at index:
        <input value={numSignal()} onInput={(e) => {
          const next = [...numbers()];
          next[index] = Number(e.target.value);
          setNumbers(next);
        }} />
      )}
    </Index>
  );
}
